<script>
(() => { const form = document.querySelector('[data-review-form]'), input = document.querySelector('[data-review-photos]'), list = document.querySelector('[data-review-photo-list]'), add = document.querySelector('[data-review-photo-add]'), files = []; const show = (key, message) => { const el = document.querySelector(`[data-review-error="${key}"]`); el.classList.toggle('hidden', !message); if (message) el.querySelector('span').textContent = message; }; const render = () => { list.querySelectorAll('[data-photo]').forEach(e => e.remove()); files.forEach((file, i) => { const holder = document.createElement('div'); holder.dataset.photo = ''; holder.className = 'relative w-14 h-14 rounded-xl overflow-hidden border border-zinc-200 dark:border-zinc-700 bg-zinc-100 dark:bg-zinc-800 shrink-0 group'; holder.innerHTML = `<img src="${URL.createObjectURL(file)}" alt="${file.name}" class="w-full h-full object-cover"><button type="button" class="absolute top-1 right-1 w-4 h-4 rounded-full bg-black/70 hover:bg-black text-white flex items-center justify-center transition-colors cursor-pointer" aria-label="Remove photo"><i data-lucide="x" class="w-2.5 h-2.5"></i></button>`; holder.querySelector('button').onclick = () => { files.splice(i, 1); render(); }; list.insertBefore(holder, add); }); add.classList.toggle('hidden', files.length >= 5); if (window.lucide) window.lucide.createIcons(); }; document.querySelectorAll('[data-review-star]').forEach(button => button.onclick = () => { form.rating.value = button.dataset.reviewStar; document.querySelector('[data-review-rating-copy]').textContent = `${form.rating.value} of 5 stars`; document.querySelectorAll('[data-review-star] i').forEach((icon, index) => icon.className = `w-6 h-6 ${index < Number(form.rating.value) ? 'fill-amber-400 text-amber-400' : 'text-zinc-300 dark:text-zinc-700'}`); show('rating', ''); }); add.onclick = () => input.click(); input.onchange = () => { [...input.files].forEach(file => { if (files.length >= 5) return show('photos', 'Up to 5 images can be uploaded.'); if (!['image/jpeg','image/png','image/webp'].includes(file.type)) return show('photos', 'Only JPEG, PNG, or WebP images are allowed.'); if (file.size > 5 * 1024 * 1024) return show('photos', 'Each image must be 5 MB or smaller.'); files.push(file); }); input.value = ''; show('photos', ''); render(); }; form.onsubmit = async event => { event.preventDefault(); const payload = new FormData(); payload.append('orderItemId', form.dataset.orderItemId); ['rating','title','comment'].forEach(key => payload.append(key, form.elements[key].value)); files.forEach(file => payload.append('images[]', file)); let valid = true; if (!form.rating.value) { show('rating', 'Please select a star rating.'); valid = false; } if (!form.title.value.trim()) { show('title', 'Please enter a review title.'); valid = false; } if (!form.comment.value.trim()) { show('comment', 'Please write your review.'); valid = false; } if (!valid) return; const button = form.querySelector('button[type="submit"]'); button.disabled = true; button.querySelector('span').textContent = 'Submitting...'; const response = await fetch(form.dataset.reviewEndpoint, { method: 'POST', headers: {'X-CSRF-TOKEN': document.querySelector('meta[name="csrf-token"]').content, 'Accept': 'application/json'}, body: payload }); if (response.ok) { form.innerHTML = '<div class="py-6 px-4 bg-zinc-50 dark:bg-zinc-950 rounded-2xl border border-zinc-200 dark:border-zinc-800 text-center space-y-2 animate-fade-in"><div class="w-10 h-10 rounded-full bg-emerald-50 dark:bg-emerald-950/60 border border-emerald-500/20 text-emerald-600 dark:text-emerald-400 flex items-center justify-center mx-auto"><i data-lucide="check" class="w-5 h-5 stroke-[2.5]"></i></div><h4 class="text-sm font-bold text-zinc-900 dark:text-white">Review submitted</h4><p class="text-xs text-zinc-500 dark:text-zinc-400">Your review will be published after approval.</p></div>'; if (window.lucide) window.lucide.createIcons(); return; } const json = await response.json(); show('photos', json.message || 'Your review could not be submitted.'); button.disabled = false; button.querySelector('span').textContent = 'Submit for review'; }; })();
</script>
